require(['jquery'], function($) {
  // Display the result of the job once it is finished: the job status only updates its log.
  var pending = $('#sopImportPending');
  var jobStatus = $('.job-status');
  if (pending.length && jobStatus.length) {
    var reloadWhenFinished = function() {
      if (!jobStatus.find('.ui-progress').length) {
        observer.disconnect();
        window.location.reload();
      }
    };
    var observer = new MutationObserver(reloadWhenFinished);
    observer.observe(jobStatus[0], {childList: true, subtree: true});
    reloadWhenFinished();
  }

  // One version per document: selecting a version unselects the other versions of the same document.
  var selection = $('#sopImportSelection');
  var updateCount = function() {
    var count = selection.find('input[name="file"]:checked').length;
    var counter = $('#sopImportSelectedCount');
    counter.text(counter.attr('data-label').replace('__count__', count));
    $('#sopImportSubmit').prop('disabled', count === 0);
  };
  selection.on('change', 'input[name="file"]', function() {
    if (this.checked) {
      $(this).closest('tr').find('input[name="file"]').not(this).prop('checked', false);
    }
    updateCount();
  });
  if (selection.length) {
    updateCount();
  }
  // The tree of the folder to import: its sub-folders, collapsed, then its documents. A document is the files of the
  // folder with the same name in different formats (e.g. a PDF and a Word document), its versions: they are selected
  // together, the analysis recommending the version to import. All the documents are selected at first; selecting or
  // unselecting a folder selects or unselects all its documents, which can then be changed one by one.
  var folderTree = $('#sopImportFolderTree');
  if (folderTree.length) {
    var fileIcons = {docx: 'fa fa-file-word-o', doc: 'fa fa-file-word-o', pdf: 'fa fa-file-pdf-o'};
    var getExtension = function(fileName) {
      return fileName.indexOf('.') < 0 ? '' : fileName.substring(fileName.lastIndexOf('.') + 1);
    };
    // The name of a file without its extension, as the import names the documents.
    var getBaseName = function(fileName) {
      return (fileName.indexOf('.') < 0 ? fileName : fileName.substring(0, fileName.lastIndexOf('.'))).trim();
    };
    // The documents of a folder: its files grouped by name, in the order of their names.
    var getDocuments = function(folder) {
      var documents = [];
      var byName = {};
      folder.files.forEach(function(fileName) {
        var baseName = getBaseName(fileName);
        if (!byName.hasOwnProperty(baseName)) {
          byName[baseName] = {name: baseName, files: []};
          documents.push(byName[baseName]);
        }
        byName[baseName].files.push(fileName);
      });
      return documents;
    };
    var toDocumentNode = function(folder, entry) {
      var prefix = folder.path ? folder.path + '/' : '';
      var extensions = entry.files.map(getExtension);
      // The icon of the version likely to be recommended for the import, else of the single file.
      var iconFile = entry.files.filter(function(fileName) {
        return folder.recommendedFiles.indexOf(fileName) >= 0;
      })[0] || entry.files[0];
      var icon = fileIcons[getExtension(iconFile).toLowerCase()] || 'fa fa-file-o';
      return {
        id: 'document:' + prefix + entry.name,
        // A single file is named as is, the versions of a document by their formats.
        text: entry.files.length === 1 ? entry.files[0]
          : entry.name + ' (' + extensions.join(', ') + ')',
        icon: icon,
        state: {selected: true},
        data: {
          type: 'document',
          paths: entry.files.map(function(fileName) {
            return prefix + fileName;
          })
        }
      };
    };
    // The documents of a folder and of all its sub-folders.
    var countDocuments = function(folder) {
      return folder.children.reduce(function(count, child) {
        return count + countDocuments(child);
      }, getDocuments(folder).length);
    };
    var toFolderNode = function(folder) {
      var documentCount = countDocuments(folder);
      var label = folderTree.attr(documentCount === 1 ? 'data-node-label-one' : 'data-node-label');
      return {
        id: 'folder:' + folder.path,
        text: label.replace('__name__', folder.name).replace('__count__', documentCount),
        icon: 'fa fa-folder-o',
        iconOpened: 'fa fa-folder-open-o',
        // Only the imported folder is expanded.
        state: {opened: folder.path === '', selected: true},
        data: {path: folder.path, type: 'folder'},
        children: folder.children.map(toFolderNode).concat(getDocuments(folder).map(function(entry) {
          return toDocumentNode(folder, entry);
        }))
      };
    };
    require(['xwiki-tree'], function() {
      folderTree.xtree({
        core: {
          data: [toFolderNode(JSON.parse(folderTree.attr('data-folders')))],
          multiple: true,
          // Keep the sub-folders collapsed, although their documents are selected.
          expand_selected_onload: false
        },
        checkbox: {
          three_state: true
        }
      });
    });
    // The files of the selected documents are submitted with the form.
    $('#sopImportForm').on('submit', function() {
      var form = $(this);
      form.find('input[name="selectedFile"]').remove();
      $.each(folderTree.jstree(true).get_selected(true), function(index, node) {
        if (node.data && node.data.type === 'document') {
          node.data.paths.forEach(function(path) {
            $('<input type="hidden" name="selectedFile" />').val(path).appendTo(form);
          });
        }
      });
    });
  }
  // The documents whose page exists are collapsed: expand them to see their details.
  selection.on('click', '.sopImportToggle', function() {
    var expanded = $(this).attr('aria-expanded') !== 'true';
    $(this).attr('aria-expanded', expanded);
    $('#' + $(this).attr('aria-controls')).toggleClass('hidden', !expanded);
  });

  // From the preview of a version, preview another version with the users selected in the preview.
  $(document).on('click', '#sopImportPreviewActions .sopImportPreviewSwitch', function() {
    var users = {};
    $('#sopImportPreviewActions .sopImportRole').each(function() {
      users['sopImportUser:' + $(this).attr('data-role')] = $(this).find('input.sopImportUser').val();
    });
    this.href += '&' + $.param(users);
  });

  // Preview a version directly in the preview mode of the editor: the window is opened on click (not blocked as a
  // popup), the content of the version is converted on the server, then sent to the preview action in this window.
  $(document).on('click', '#sopImportAnalysisTable .sopImportPreviewLink', function(event) {
    event.preventDefault();
    var link = $(this);
    var windowName = 'sopImportPreview' + new Date().getTime();
    var previewWindow = window.open('', windowName);
    if (!previewWindow) {
      // The window could not be opened: preview in this window.
      window.location = link.attr('href');
      return;
    }
    $.get(link.attr('href'), {'xpage': 'plain'}).done(function(html) {
      // Without running the script of the page, which submits the form.
      var form = $('<div></div>').append($.parseHTML(html)).find('#sopImportPreviewForm');
      if (form.length) {
        // The users selected in the analysis, to import the version with them from the preview.
        link.closest('tr').find('.sopImportRole').each(function() {
          var role = $(this).attr('data-role');
          form.find('input[name="sopImportUser:' + role + '"]').val($(this).find('input.sopImportUser').val());
        });
        form.attr('target', windowName).addClass('hidden').appendTo(document.body);
        form[0].submit();
        form.remove();
      } else {
        previewWindow.location = link.attr('href');
      }
    }).fail(function() {
      previewWindow.location = link.attr('href');
    });
  });
});

#sopImportForm input[type="text"] {
  max-width: 40em;
}
#sopImportFolderForm input[type="text"] {
  max-width: 40em;
}
#sopImportFolderTree {
  margin: .5em 0 1em;
  max-height: 30em;
  overflow: auto;
}
#sopImportAnalysisTable .sopImportFolderRow th {
  background-color: #eef3f7;
}
#sopImportReport .sopImportDetails ul, .sopImportWarnings {
  margin-bottom: 0;
  padding-left: 1.2em;
}
#sopImportReport .sopImportDetails p, #sopImportAnalysisTable p {
  margin: 0 0 .3em;
}
#sopImportAnalysisTable td {
  vertical-align: top;
}
#sopImportAnalysisTable .sopImportMissing {
  color: #999;
  text-align: center;
  vertical-align: middle;
}
#sopImportAnalysisTable .label, #sopImportAnalysisTable .btn {
  display: inline-block;
  max-width: 100%;
  white-space: normal;
}
#sopImportAnalysisTable .sopImportVersionFile {
  font-weight: normal;
  word-break: break-all;
}
#sopImportAnalysisTable .sopImportRecommendedVersion {
  background-color: rgba(92, 184, 92, .08);
}
#sopImportAnalysisTable details summary {
  cursor: pointer;
  font-size: .9em;
  color: #777;
}
/* Fixed layout, so that long values wrap instead of widening the cell. */
.sopImportProperties {
  table-layout: fixed;
  width: 100%;
  margin: .3em 0;
  font-size: .9em;
}
.sopImportProperties th, .sopImportProperties td {
  padding: 0 .8em 0 0;
  vertical-align: top;
  border: 0;
}
.sopImportProperties th {
  width: 40%;
  font-weight: normal;
  color: #777;
}
/* The table fits the width of the page content: the columns don't grow with their content. */
#sopImportAnalysisTable {
  table-layout: fixed;
  width: 100%;
  max-width: 100%;
  font-size: .9em;
}
#sopImportAnalysisTable .sopImportDocumentColumn {
  width: 40%;
}
#sopImportAnalysisTable td, #sopImportAnalysisTable th {
  overflow-wrap: anywhere;
}
.sopImportRole {
  margin-top: .3em;
}
.sopImportRoleName {
  display: block;
  margin: 0;
}
/* The user pickers, as small as the rest of the text (selectize up to XWiki 17, Tom Select from XWiki 18). */
.sopImportRole .selectize-control, .sopImportRole .ts-wrapper {
  max-width: 100%;
  margin-top: .2em;
  font-size: inherit;
}
.sopImportRole .selectize-input, .sopImportRole .ts-control {
  min-height: 0;
  padding: 2px 6px;
  font-size: inherit;
  line-height: 1.5;
}
/* Less room kept for the loading spinner (and the arrow of the single picker). */
.sopImportRole .selectize-control.multi .selectize-input, .sopImportRole .ts-wrapper.multi .ts-control {
  padding-right: 22px;
}
.sopImportRole .selectize-control.single .selectize-input, .sopImportRole .ts-wrapper.single .ts-control {
  padding-right: 42px;
}
/* Long user names wrap instead of widening the picker. */
.sopImportRole .xwiki-selectize-option {
  max-width: 100%;
  white-space: normal;
}
.sopImportRole .selectize-dropdown .xwiki-selectize-option, .sopImportRole .ts-dropdown .xwiki-selectize-option {
  white-space: nowrap;
}
.sopImportRole .selectize-input > input, .sopImportRole .ts-control > input {
  height: auto;
  min-width: 0;
  font-size: inherit;
}
.sopImportRole .selectize-dropdown, .sopImportRole .ts-dropdown {
  font-size: inherit;
}
.sopImportExists {
  font-size: .9em;
}
#sopImportAnalysisTable .sopImportExistingCandidate td {
  background-color: #f5f5f5;
}
#sopImportAnalysisTable .sopImportToggle {
  padding: 0 .5em 0 0;
  color: inherit;
}
#sopImportAnalysisTable .sopImportToggle::before {
  content: '\25B8';
  display: inline-block;
  width: 1em;
}
#sopImportAnalysisTable .sopImportToggle[aria-expanded="true"]::before {
  content: '\25BE';
}
#sopImportPreviewActions h3 {
  margin-top: 0;
  font-size: 1.1em;
}
#sopImportPreviewActions .panel-heading p {
  margin: 0;
}
#sopImportPreviewActions .sopImportPreviewVersion {
  margin-bottom: .5em;
  padding: .3em .5em;
  border-left: 3px solid #ddd;
}
#sopImportPreviewActions .sopImportPreviewVersion p {
  margin: 0 0 .2em;
}
#sopImportPreviewActions .sopImportRecommendedVersion {
  border-left-color: #5cb85c;
  background-color: rgba(92, 184, 92, .08);
}
#sopImportPreviewActions .sopImportUsers, #sopImportPreviewActions .sopImportPreviewData {
  overflow-wrap: anywhere;
}
